describe('Personal Data Export to JSON', () => {
  beforeEach(() => {
    cy.visit('/user/profile');
  });

  it('should successfully export user data as a JSON file', () => {
    // Intercept the API call for data export
    cy.intercept('GET', '/api/user/data/export').as('exportData');

    // Click the export button
    cy.get('[data-testid="export-button"]').click();

    // Wait for the API call
    cy.wait('@exportData');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Data exported successfully');

    // Verify download link or button appears
    cy.get('[data-testid="download-json-link"]').should('be.visible');

    // Click the download link
    cy.get('[data-testid="download-json-link"]').click();

    // Verify file download prompt or confirmation
    cy.get('[data-testid="download-confirmation"]').should('be.visible').should('contain', 'File download started');

    // Verify the file name is correct
    cy.get('[data-testid="download-filename"]').should('contain', 'user-data.json');
  });

  it('should handle API errors during data export', () => {
    // Intercept the API call and mock an error response
    cy.intercept('GET', '/api/user/data/export', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('exportDataError');

    // Click the export button
    cy.get('[data-testid="export-button"]').click();

    // Wait for the error API call
    cy.wait('@exportDataError');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Failed to export data');

    // Verify error details are shown
    cy.get('[data-testid="error-details"]').should('be.visible').should('contain', 'Internal server error');

    // Verify download link does not appear
    cy.get('[data-testid="download-json-link"]').should('not.exist');

    // Verify user can retry the export
    cy.get('[data-testid="retry-export-button"]').should('be.visible');
  });
});
